// Monta e-mails de "cliente regularizou" no padrao visual Sebratel (600px, email-safe).
// Regras herdadas do template de indicadores: marca (vermelho) so na regua de
// topo e no lockup; status usa verde; layout em tabelas com estilo inline; sem
// imagem (o proxy do Gmail nao alcanca o painel interno).
const T = {
  g900:'#101828', g800:'#1d2939', g700:'#344054', g600:'#475467', g500:'#667085',
  g300:'#d0d5dd', g200:'#eaecf0', g100:'#f2f4f7', g50:'#f9fafb',
  white:'#ffffff',
  okText:'#067647', okBg:'#ecfdf3', okBorder:'#abefc6',
  badText:'#b42318', badBg:'#fef3f2', badBorder:'#fecdca',
  warnText:'#b54708',
  brand:'#dc1c24',
};

// URL publica do painel (opcional). Vazio = sem botao, para nao deixar link morto.
const PAINEL_URL = '';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const brl = (v) => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

function pill(txt, fg, bg, bd) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg + ';border:1px solid ' + bd +
    ';border-radius:9px;padding:2px 8px;font-size:11px;font-weight:600;line-height:1.5;white-space:nowrap;">' + txt + '</span>';
}

function shell(opts) {
  const geradoEm = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const temBotao = PAINEL_URL && opts.caseId;
  return '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light only">' +
    '<title>' + esc(opts.title) + '</title></head>' +
    '<body style="margin:0;padding:0;background:' + T.g100 + ';font-family:-apple-system,BlinkMacSystemFont,Segoe UI,system-ui,Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased;">' +
    '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;background:' + T.g100 + ';">' +
    '<tr><td align="center" style="padding:20px 8px;">' +
    '<table width="600" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;width:600px;max-width:600px;background:' + T.white + ';border:1px solid ' + T.g200 + ';border-radius:10px;overflow:hidden;">' +
    '<tr><td style="height:3px;background:' + T.brand + ';font-size:0;line-height:0;">&nbsp;</td></tr>' +
    '<tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;"><tr>' +
    '<td valign="middle" style="padding:17px 20px 13px;">' +
    '<div style="font-size:14.5px;font-weight:800;letter-spacing:.16em;color:' + T.brand + ';line-height:1;">SEBRATEL</div>' +
    '<div style="font-size:7.5px;font-weight:600;letter-spacing:.14em;color:' + T.g500 + ';padding-top:4px;line-height:1;">TELECOMUNICACOES</div>' +
    '</td>' +
    '<td align="right" valign="middle" style="padding:17px 20px 13px;">' +
    '<div style="font-size:8.5px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:' + T.g500 + ';line-height:1;">' + esc(opts.contextLabel) + '</div>' +
    '<div style="font-size:13px;font-weight:600;color:' + T.g900 + ';padding-top:5px;line-height:1;white-space:nowrap;">' + esc(opts.contextValue) + '</div>' +
    '</td></tr>' +
    '<tr><td colspan="2" style="padding:0 20px;"><div style="height:1px;background:' + T.g200 + ';font-size:0;line-height:0;">&nbsp;</div></td></tr>' +
    '<tr><td colspan="2" style="padding:14px 20px 17px;">' +
    '<div style="font-size:19px;font-weight:600;color:' + T.g900 + ';letter-spacing:-.022em;line-height:1.25;">' + esc(opts.title) + '</div>' +
    (opts.subtitle ? '<div style="font-size:11.5px;color:' + T.g500 + ';padding-top:5px;line-height:1.45;">' + esc(opts.subtitle) + '</div>' : '') +
    '</td></tr></table></td></tr>' +
    '<tr><td style="padding:0;">' + opts.bodyHtml + '</td></tr>' +
    '<tr><td style="padding:16px 20px 20px;background:' + T.g50 + ';border-top:1px solid ' + T.g200 + ';">' +
    (temBotao ? '<a href="' + PAINEL_URL + '/supervisao/' + encodeURIComponent(opts.caseId) + '" style="display:inline-block;background:' + T.g900 + ';color:' + T.white + ';font-size:11.5px;font-weight:600;text-decoration:none;padding:10px 17px;border-radius:7px;">Ver no painel &rarr;</a>' : '') +
    '<div style="font-size:10px;color:' + T.g500 + ';line-height:1.6;' + (temBotao ? 'padding-top:13px;' : '') + '">Notificacao automatica da plataforma de cobranca &middot; ' + geradoEm + '.</div>' +
    '</td></tr></table></td></tr></table></body></html>';
}

// E-mail do atendente: um cliente regularizado (destaque verde).
function bodyAtendente(c) {
  const promessa = c.hadActivePromise;
  const selo = pill(promessa ? '&#10003; Promessa cumprida' : '&#10003; Pagamento confirmado', T.okText, T.okBg, T.okBorder);
  return '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">' +
    '<tr><td style="padding:4px 20px 0;">' +
    '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:separate;border:1px solid ' + T.okBorder + ';border-radius:10px;background:' + T.okBg + ';">' +
    '<tr><td style="padding:18px 20px 20px;">' +
    '<div>' + selo + '</div>' +
    '<div style="font-size:18px;font-weight:700;color:' + T.g900 + ';letter-spacing:-.01em;padding-top:12px;line-height:1.25;">' + esc(c.customerName) + '</div>' +
    '<div style="font-size:28px;font-weight:800;color:' + T.okText + ';letter-spacing:-.02em;font-variant-numeric:tabular-nums;padding-top:6px;line-height:1.1;">' + brl(c.recoveredAmount) + '</div>' +
    '<div style="font-size:11px;color:' + T.g500 + ';padding-top:3px;">valor regularizado</div>' +
    '</td></tr></table></td></tr>' +
    '<tr><td style="padding:16px 20px 4px;">' +
    '<div style="font-size:13px;color:' + T.g700 + ';line-height:1.55;">Este cliente da sua carteira ' + (promessa ? 'cumpriu a promessa e ' : '') + 'regularizou o pagamento. Nenhuma acao de cobranca e necessaria.</div>' +
    '<div style="font-size:11px;color:' + T.g500 + ';padding-top:10px;">Caso <span style="color:' + T.g700 + ';font-weight:600;">' + esc(c.caseId) + '</span></div>' +
    '</td></tr></table>';
}

// E-mail da supervisao: resumo consolidado da rodada.
function bodySupervisao(summary, cases) {
  const tile = (valor, rotulo, cor) =>
    '<td width="50%" valign="top" style="padding:14px 8px 14px 20px;">' +
    '<div style="font-size:9px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:' + T.g500 + ';line-height:1.3;">' + rotulo + '</div>' +
    '<div style="font-size:24px;font-weight:700;line-height:1.1;letter-spacing:-.02em;padding-top:4px;color:' + cor + ';font-variant-numeric:tabular-nums;">' + valor + '</div></td>';

  const listItens = cases.slice(0, 10).map(function (c, i, arr) {
    const ultima = i === arr.length - 1;
    const agente = c.agent && c.agent.name ? esc(c.agent.name) : 'Sem responsavel';
    return '<tr><td style="padding:9px 0 ' + (ultima ? '0' : '9') + 'px;' + (ultima ? '' : 'border-bottom:1px solid ' + T.g200 + ';') + '">' +
      '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;"><tr>' +
      '<td valign="top"><div style="font-size:12.5px;font-weight:600;color:' + T.g900 + ';line-height:1.3;">' + esc(c.customerName) + (c.hadActivePromise ? ' ' + pill('promessa', T.okText, T.okBg, T.okBorder) : '') + '</div>' +
      '<div style="font-size:10px;color:' + T.g500 + ';padding-top:2px;">' + agente + '</div></td>' +
      '<td align="right" valign="top" style="white-space:nowrap;"><span style="font-size:14px;font-weight:700;color:' + T.okText + ';font-variant-numeric:tabular-nums;">' + brl(c.recoveredAmount) + '</span></td>' +
      '</tr></table></td></tr>';
  }).join('');

  const resto = cases.length > 10 ? '<div style="font-size:10.5px;color:' + T.g600 + ';padding-top:10px;">+ ' + (cases.length - 10) + ' outros clientes.</div>' : '';

  return '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">' +
    '<tr><td style="padding:0;background:' + T.g50 + ';border-top:1px solid ' + T.g200 + ';border-bottom:1px solid ' + T.g200 + ';">' +
    '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;"><tr>' +
    tile(String(summary.count), 'Clientes', T.g900) +
    tile(brl(summary.totalAmount), 'Recuperado', T.okText) +
    '</tr></table></td></tr>' +
    '<tr><td style="padding:16px 20px 6px;">' +
    '<div style="font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:' + T.g500 + ';padding-bottom:4px;">Clientes regularizados</div>' +
    '<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">' + listItens + '</table>' +
    resto +
    '</td></tr></table>';
}

// ---- Entrada do n8n ---------------------------------------------------------
const first = $input.first();
const body = first && first.json && first.json.body ? first.json.body : (first ? first.json : {});
const cases = Array.isArray(body.cases) ? body.cases : [];
const supervisorEmails = Array.isArray(body.supervisorEmails) ? body.supervisorEmails : [];
const summary = body.summary || { count: cases.length, totalAmount: 0 };
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const out = [];

// 1) Um e-mail para o atendente responsavel de cada caso da carteira dele.
for (const c of cases) {
  if (!c.agent || !c.agent.email) continue;
  const title = c.hadActivePromise ? 'Promessa cumprida' : 'Cliente regularizou o pagamento';
  out.push({ json: {
    tipo: 'atendente',
    to: c.agent.email,
    subject: (c.hadActivePromise ? 'Promessa cumprida - ' : 'Cliente regularizou - ') + c.customerName,
    html: shell({
      contextLabel: 'Regularizacao', contextValue: hoje,
      title: title, subtitle: 'Um cliente da sua carteira regularizou a situacao.',
      caseId: c.caseId, bodyHtml: bodyAtendente(c),
    }),
  } });
}

// 2) Um resumo consolidado para a supervisao.
if (supervisorEmails.length > 0) {
  const title = summary.count === 1 ? '1 cliente regularizou o pagamento' : summary.count + ' clientes regularizaram o pagamento';
  out.push({ json: {
    tipo: 'supervisao',
    to: supervisorEmails.join(','),
    subject: title + ' - ' + brl(summary.totalAmount) + ' recuperado',
    html: shell({
      contextLabel: 'Regularizacoes', contextValue: hoje,
      title: title, subtitle: 'Resumo da ultima sincronizacao.',
      bodyHtml: bodySupervisao(summary, cases),
    }),
  } });
}

return out;
